def generate(repo, root, check=False):
    mismatches = []
    for name, content in artifacts(repo).items():
        path = root / name
        if path.is_symlink():
            raise ValueError(f"Refusing generated symlink: {name}")
        expected = content.encode("utf-8")
        if check:
            if not path.is_file() or path.read_bytes() != expected:
                mismatches.append(name)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(expected)
    if mismatches:
        raise ValueError("Generated setup differs: " + ", ".join(mismatches))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repository", choices=PROFILES["repositories"])
    parser.add_argument("--root", type=Path)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    try:
        if args.repository:
            generate(args.repository, args.root or Path.cwd(), args.check)
        else:
            if args.root is None:
                parser.error("--root is required for all-repository generation")
            for repo in PROFILES["repositories"]:
                generate(repo, args.root / repo, args.check)
        print("Public repository baseline " + ("verified." if args.check else "generated."))
        return 0
    except (OSError, ValueError) as error:
        print(str(error), file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
